from pathlib import Path
import html,json,re,shutil
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent;C=Path('/tmp/medina-source-cache/endocrinologie/E04')
assert not (D/'source-binding.json').exists(),'Final evidence sealed; never refresh automatically.'
assert 'VÉRITÉ OK' in (D/'research-gate.log').read_text()
ledger=json.loads((D/'source-ledger.json').read_text())['sources'];pops=[];summaries=[]
def w(k,label):return f'<button class="w" data-k="e04-{k}">{label}</button>'
def table(h,rows):return '<table class="t" data-e04-table="1"><thead><tr>'+''.join('<th>'+x+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def pop(k,title,body):pops.append(f'<template data-pop="e04-{k}" data-title="{html.escape(title,quote=True)}">{body}</template>')
def sec(k,title,body,summary):
 a='e04-'+str(k);pk='pareto-'+a;summaries.append(f'<template data-pop="{pk}" data-title="Essentiel — {html.escape(title,quote=True)}"><p>{summary}</p><p class="ratio" data-cover="{a}"></p></template>')
 return f'<section class="ilot" id="{a}"><h2><span class="n">{k}</span>{title}</h2>{body}<div class="key"><b>À retenir.</b> {summary}</div><button class="pareto-btn ui" data-k="{pk}">Essentiel de cette partie</button></section>'
def logical(a,b,c,caption):
 t='<figure><svg role="img" viewBox="0 0 450 246" aria-label="Schéma logique sans anatomie générée">'
 for i,label in enumerate([a,b,c]):
  y=5+80*i;t+=f'<rect x="8" y="{y}" width="434" height="54" rx="8" fill="none" stroke="currentColor"/><text x="225" y="{y+33}" font-size="17" fill="currentColor" text-anchor="middle">{label}</text>'
  if i<2:t+=f'<path d="M225 {y+54}v26m-5-7 5 7 5-7" stroke="currentColor" fill="none"/>'
 return t+'</svg><figcaption>Schéma logique original Sol2026, sans anatomie générée. '+caption+'</figcaption></figure>'
S=[]
S.append(sec(1,'Une masse cervicale avec une fonction normale','''<p>Une patiente fictive de cinquante-six ans consulte parce que son col devient serré. Elle ne décrit ni palpitations ni amaigrissement ; une prise de sang antérieure était annoncée normale. À la palpation, la thyroïde paraît augmentée et irrégulière. Il reste pourtant trois questions différentes : existe-t-il une complication mécanique, quelle est la fonction hormonale, et les nodules comportent-ils un risque tumoral ? Une réponse rassurante à une question ne répond pas aux deux autres [S3, S4].</p><p>Le mot « non toxique » signifie que le goitre n’est pas associé à une hyperthyroïdie dans le tableau considéré. Il ne signifie pas « sans danger », « non compressif » ou « cancer exclu ». Une thyroïde peut augmenter de volume tout en maintenant une production hormonale normale ; un cancer peut aussi se présenter chez une personne euthyroïdienne [S2–S4].</p><p>La formation suisse PROFILES demande d’inspecter et palper la thyroïde et les structures cervicales, de raisonner devant un gonflement du cou ou un goitre, et d’interpréter des hormones thyroïdiennes anormales. Ces objectifs soutiennent cette démarche, sans constituer une correspondance officielle entre un code et une question d’examen. La vignette et ses données sont pédagogiques [S16].</p>''','Séparer gravité mécanique, fonction et risque tumoral. Une analyse hormonale normale ne remplace pas l’examen du cou [S3, S4].'))
S.append(sec(2,'Définition et sous-codes : documenter avant de classer','''<p>Le catalogue suisse local2024 donne E04 — Autres goitres non toxiques. Un goitre décrit une augmentation de la glande ; un nodule est une lésion qui se distingue du tissu environnant à l’échographie. La présence d’un petit nodule n’implique donc pas à elle seule que tout le volume glandulaire soit augmenté. Décrire la morphologie et la fonction évite de confondre ces dimensions [S1–S4].</p>'''+table(['Sous-code suisse','Libellé','Précision utile'],[['E04.0','Goitre diffus non toxique','Augmentation diffuse ; les notes allemandes incluent goitre simple et colloïde.'],['E04.1','Nodule thyroïdien simple non toxique','Nodule unique, notamment kystique selon les inclusions ; « simple » ne remplace pas évaluation du risque.'],['E04.2','Goitre multinodulaire non toxique','Plusieurs nodules, y compris formes kystiques multiples.'],['E04.8','Autres goitres non toxiques précisés','Une forme précisée ne relevant pas des précédentes doit être documentée.'],['E04.9','Goitre non toxique, sans précision','Réserver à une documentation insuffisante ; ne pas effacer une morphologie connue.']])+'''<p>Les notes excluent les goitres liés à une carence en iode, classés E00–E02, et le goitre congénital diffus, classé E03.0. Une histoire ancienne de carence régionale peut contribuer au terrain nodulaire ; elle ne prouve pas à elle seule la cause actuelle d’un goitre individuel. À l’inverse, une carence iodée causale établie demande de reconsidérer le code [S1, S2].</p><p>Les libellés français proviennent des métadonnées suisses locales ; les inclusions/exclusions ont été confrontées au texte allemand2024. Le PDF OFS intégral n’a pas été relu pour cette leçon : il ne s’agit pas d’une certification de codage individuel ou de remboursement [S1, S2].</p>''','Couvrir E04.0, .1, .2, .8 et .9 ; ne pas classer automatiquement ici un goitre par carence iodée ou une maladie congénitale [S1, S2].'))
S.append(sec(3,'Fréquence : nodules, goitres et statut iodé','''<p>Aucune incidence suisse contemporaine spécifique de E04 n’a été établie dans les lectures ciblées. L’absence de chiffre dans ce dossier ne démontre pas l’absence de maladie. Une série de nodules découverts à l’échographie, un registre de chirurgie et une enquête sur l’iode ne mesurent pas le même événement [S3, S9, S17].</p><p>Le guide européen2023 indique que des nodules peuvent être détectés chez jusqu’à60% des adultes selon les populations et la méthode d’imagerie. Ils deviennent plus fréquents avec l’âge et sont plus souvent trouvés chez les femmes. Ce chiffre ne représente ni la prévalence suisse des goitres E04 ni une indication de dépister tout adulte asymptomatique. Le guide estime le risque de malignité autour de1–5% dans des populations non sélectionnées ; une consultation spécialisée ou une sélection chirurgicale change le dénominateur [S3].</p><p>En Suisse, le monitoring2020–2022 a mesuré une iodurie médiane de127µg/l chez362enfants de six à douze ans, et de97µg/l chez473femmes enceintes. La couverture était considérée adéquate chez les enfants et insuffisante au niveau populationnel chez les femmes enceintes. Ces concentrations urinaires ne comptent pas les goitres et un échantillon urinaire isolé ne devient pas un diagnostic individuel de carence causale [S9].</p><p>Chez les femmes enceintes de cette enquête,47% déclaraient un supplément ; les médianes étaient88µg/l sans supplément et140µg/l avec. L’amélioration du marqueur ne permet pas d’affirmer que toute personne supplémentée atteignait l’objectif, ni que tout goitre suisse était lié à une carence [S9].</p>''','Toujours nommer la population, la méthode et le dénominateur. Une fréquence de nodules n’est pas une incidence E04 [S3, S9].'))
S.append(sec(4,'Du follicule normal au volume nodulaire','''<p>La thyroïde normale comprend deux lobes réunis par un isthme devant la trachée. Les cellules folliculaires entourent une lumière contenant la colloïde et la thyroglobuline. Elles captent l’iodure, fabriquent les hormones et les libèrent sous le contrôle de la thyréostimuline hypophysaire, ou TSH. Le rétrocontrôle ajuste la production ; la taille et l’architecture ne se déduisent pas directement d’un seul dosage [S14].</p><p>Une prolifération, une accumulation de colloïde, une dégénérescence kystique ou des remaniements de nodules peuvent augmenter le volume sans entraîner immédiatement une hyperthyroïdie. Un goitre multinodulaire est hétérogène : tous les nodules n’ont pas forcément la même fonction, la même structure ou le même risque [S3, S4].</p><p>Une croissance vers les espaces profonds peut déplacer ou comprimer la trachée et l’œsophage. L’effet dépend du siège, de la forme et des rapports anatomiques, pas seulement du diamètre maximal externe. C’est pourquoi des symptômes respiratoires, une dysphagie ou une modification de voix doivent être explorés même si le bilan hormonal reste normal [S3, S4].</p><p>Enfin, une zone peut devenir autonome et répondre moins au contrôle hypophysaire. La TSH peut alors baisser, parfois avant l’augmentation des hormones libres. Une charge iodée importante peut révéler une production excessive sur ce terrain ; une fonction normale au départ n’élimine pas toute autonomie ni tout risque après contraste [S3, S12].</p>'''+logical('Structure et volume','Fonction hormonale','Risque et retentissement','Trois dimensions à évaluer ensemble ; les flèches organisent le raisonnement, elles ne décrivent pas une succession obligatoire [S3, S4, S12].'),'Le volume, la fonction et la nature du tissu sont liés mais distincts. Le follicule normal aide à comprendre cette séparation [S3, S14].'))
S.append(sec(5,'Causes, risques et diagnostics à ne pas confondre','''<p>L’histoire iodée et familiale, l’âge, les antécédents de maladie thyroïdienne et les expositions participent au raisonnement. Un médicament iodé ou une injection de contraste doit être recherché, surtout lorsqu’une anomalie fonctionnelle apparaît. Les compléments alimentaires et les algues peuvent aussi apporter des quantités variables d’iode ; « naturel » ne signifie pas dose faible et constante [S3, S8, S12].</p><p>Une irradiation cervicale pendant l’enfance, une histoire familiale de cancer thyroïdien ou de syndrome de prédisposition renforcent l’attention portée à une lésion. Ils ne prouvent pas qu’un nodule donné est malin. Des nodules multiples et apparemment bénins ne dispensent pas d’identifier les plus suspects à l’échographie [S3, S13].</p><p>Une thyroïdite auto-immune ou inflammatoire peut augmenter le volume et produire des zones ressemblant à des nodules. Une maladie de Basedow peut donner un goitre avec hyperthyroïdie ; une tumeur, un ganglion ou une lésion d’un autre organe cervical peut imiter une masse thyroïdienne. Ces hypothèses demandent leur évaluation et, lorsqu’elles sont établies, leur classification propre [S2, S3, S12].</p><p>Chez l’enfant ou en présence de manifestations syndromiques, certaines prédispositions comme DICER1 ou le syndrome lié à PTEN peuvent s’accompagner d’un goitre multinodulaire. Elles justifient une orientation ciblée selon l’ensemble clinique et familial, pas un séquençage systématique de tout adulte présentant E04 [S13].</p>''','Le contexte oriente sans remplacer l’évaluation du nodule. Un goitre est une description qui demande encore une explication [S2, S3, S13].'))
S.append(sec(6,'Anamnèse : évolution, compression et expositions','''<p>Préciser date de découverte, changement du volume, douleur ou gonflement soudain, gêne esthétique, difficulté à avaler, voix modifiée, dyspnée et gêne en position couchée. Une aggravation rapide ne se résume pas à « le goitre a grandi » : elle peut traduire une hémorragie, une inflammation ou un processus tumoral et doit être confrontée à l’état respiratoire [S3, S4].</p><p>Demander symptômes de fonction excessive ou insuffisante, antécédents de chirurgie, irradiation, ponction et résultats anciens. Une ancienne cytologie dite bénigne est utile si l’on sait quel nodule avait été ponctionné, à quelle date et avec quelle concordance échographique. Un goitre ancien n’assure pas que toute nouvelle modification est sans importance [S3].</p><p>Rechercher antécédents familiaux de cancer, notamment médullaire, et de néoplasie endocrinienne multiple de type2. Documenter grossesse, projet de grossesse, allaitement, comorbidités cardiaques et rénales, ainsi que médicaments, biotine, amiodarone, hormones, iode et contraste récent. Ces éléments peuvent modifier le choix des examens et traitements [S3, S5, S6, S12].</p><p>Enfin, demander ce qui gêne réellement la personne et ce qu’elle attend : rassurance argumentée, amélioration de la déglutition, réduction du volume ou certitude diagnostique. Surveillance et intervention ont chacune des contraintes ; expliquer les alternatives est une partie du soin [S3, S4].</p>''','La chronologie et les symptômes de compression sont aussi utiles que l’ancienne prise de sang. Identifier les expositions avant de choisir un examen [S3, S12].'))
S.append(sec(7,'Sémiologie clinique : examiner le cou et la respiration','''<div data-semiology-clinical="E04"><p>La sémiologie clinique commence par l’état général, la respiration et la voix, puis relie inspection, palpation et bilan. Une masse mobile à la déglutition est compatible avec une origine thyroïdienne mais ne suffit pas à affirmer sa nature bénigne. Un examen rassurant ne remplace pas une échographie indiquée [S3, S14].</p></div><p>Inspecter le cou au repos et pendant la déglutition, rechercher asymétrie, augmentation visible et circulation veineuse anormale. Palper doucement les lobes et l’isthme, apprécier consistance, mobilité, douleur, contours et nodules perceptibles. Examiner les aires ganglionnaires cervicales. Noter si le pôle inférieur est accessible ; la palpation n’exclut pas une extension rétrosternale [S3, S4, S14, S16].</p><p>Une lésion dure ou fixée, un ganglion suspect, une voix nouvellement rauque ou une croissance préoccupante renforcent la suspicion et accélèrent l’évaluation. Leur absence ne constitue pas un test d’exclusion du cancer. Aucune sensibilité ou spécificité universelle de la palpation n’est établie dans les lectures : la performance dépend notamment de la taille, du siège et de l’examinateur [S3].</p><p>Décrire les signes fonctionnels avec fréquence cardiaque, tremblement et autres observations pertinentes. Un tableau hormonal doit être confirmé biologiquement et expliqué ; ne pas transformer l’absence de tremblement en preuve d’euthyroïdie. Une détresse respiratoire fait passer les soins urgents avant le bilan ambulatoire complet [S3, S4, S12].</p>''','Observer et décrire avant de conclure. Ni la mobilité à la déglutition ni l’absence de symptômes hormonaux ne certifient un nodule bénin [S3].'))
S.append(sec(8,'Drapeaux rouges : choisir le délai et le niveau de soins','''<div class="alert"><b>Urgence respiratoire.</b> Stridor, détresse respiratoire ou aggravation aiguë avec gêne majeure imposent une évaluation urgente des voies aériennes et une équipe adaptée. Ne pas attendre une ponction programmée ou l’effet retardé du radioiode pour décomprimer une situation critique [S3, S4, S6].</div>'''+table(['Observation','Question','Action'],[['Gonflement soudain, douleur, gêne respiratoire','Hémorragie ou autre complication compressive ?','Évaluation urgente selon retentissement, sécurisation respiratoire si nécessaire.'],['Voix modifiée, masse fixée, ganglion suspect, croissance inquiétante','Atteinte nerveuse ou lésion tumorale ?','Évaluation spécialisée accélérée, échographie et prélèvement ciblé selon contexte.'],['Dyspnée positionnelle, dysphagie, goitre profond','Extension rétrosternale et rapports trachée/œsophage ?','Imagerie d’extension et discussion spécialisée ; urgence selon gravité.'],['Palpitations ou décompensation après contraste','Hyperthyroïdie induite sur autonomie ?','Fonction thyroïdienne et évaluation clinique, prise en charge rapide si état cardiaque/clinique préoccupant.']])+'''<p>Aucun délai numérique unique n’est applicable à tous les signes suspects. Le guide européen distingue les caractéristiques préoccupantes et les indications d’investigation ; la priorité concrète dépend de la respiration, de l’évolution et des ressources. Un symptôme stable mérite également une réponse organisée et un contact en cas d’aggravation [S3, S4].</p><p>Le radioiode réduit progressivement le volume ; une inflammation ou un gonflement transitoire peut survenir. Il n’est donc pas une réponse à un besoin de décompression trachéale rapide. Une suspicion de cancer demande son propre parcours diagnostique, avant un traitement de réduction supposé bénin [S4, S6].</p>''','La fonction normale ne protège pas d’une compression. La gravité respiratoire fixe la priorité [S3, S4].'))
S.append(sec(9,'Explorations : une question pour chaque examen','''<p>Le bilan initial associe histoire, examen, fonction thyroïdienne et échographie cervicale. La TSH est le premier test biologique ; si elle est basse, mesurer la thyroxine libre, puis la triiodothyronine libre si la première est normale. Si elle est élevée, mesurer thyroxine libre et anticorps antithyroperoxydase selon la situation. Les intervalles de référence dépendent du laboratoire, de la méthode, de l’âge et de la grossesse : pas de norme numérique unique attribuée à tout E04 [S3, S5].</p><p>L’échographie décrit volume glandulaire, caractéristiques et dimensions des nodules, ainsi que ganglions centraux et latéraux. Dans un goitre multiple, la sélection ne porte pas seulement sur le plus gros nodule. La catégorie EU-TIRADS et les signes d’extension ou ganglions suspects aident à choisir la cytoponction ; le score ne comprend pas à lui seul l’examen ganglionnaire [S3].</p><p>La scintigraphie renseigne sur la fonction régionale ; elle est indiquée si la TSH est sous la normale. Dans un terrain de carence iodée actuelle ou ancienne et un goitre multinodulaire, elle peut aussi être discutée avec TSH normale. Un nodule hyperfonctionnel n’est généralement pas ponctionné sauf suspicion particulière ; « chaud » ne signifie toutefois pas impossibilité absolue de cancer [S3].</p><p>Une tomodensitométrie ou une imagerie par résonance magnétique sert à évaluer extension profonde et rapports compressifs, pas à remplacer systématiquement l’échographie initiale. Le contraste iodé demande une évaluation du risque fonctionnel et peut perturber une scintigraphie ou un radioiode ultérieurs. La thyroglobuline sanguine n’est pas un test initial de dépistage du cancer nodulaire ; le dosage de calcitonine est ciblé selon le contexte, sans consensus européen pour ou contre son dosage chez tout nodule [S3, S12].</p>''','L’échographie mesure la structure, la scintigraphie la fonction régionale et la cytologie les cellules. Leurs résultats ne sont pas interchangeables [S3].'))
S.append(sec(10,'Différentiels : ce qui change réellement la décision','''<p>Un goitre diffus ou nodulaire euthyroïdien n’est retenu qu’après confrontation au contexte. La dénomination E04 ne doit pas servir à fermer le diagnostic devant une maladie causale ou un cancer documentés [S1–S3].</p>'''+table(['Hypothèse','Élément discriminant','Conséquence'],[['Goitre lié à carence iodée','Contexte et carence causale établie, pas seule iodurie ponctuelle.','Étiologie et code E00–E02 à reconsidérer.'],['Goitre toxique / autonomie','TSH basse, hormones et scintigraphie selon situation.','Parcours de dysfonction, pas simple maintien E04 par ancien libellé.'],['Thyroïdite','Douleur ou contexte inflammatoire/auto-immun, biologie et aspect diffus concordants.','Reconnaître maladie causale ; pseudo-nodule possible.'],['Cancer thyroïdien','Signes échographiques, ganglion, cytologie/histologie selon cas.','Fonction normale non exclusive ; parcours spécialisé.'],['Kyste ou nodule bénin','Aspect et cytologie si indiquée, concordance clinique.','Surveillance ou traitement selon gêne, récidive et risque.'],['Masse non thyroïdienne','Rapports anatomiques, échographie et examen ganglionnaire.','Autre origine cervicale, exploration ciblée.']])+'''<p>Une cytologie bénigne discordante avec une échographie très suspecte mérite une réévaluation. Un prélèvement non diagnostique n’est pas synonyme de bénignité ; une cytologie folliculaire indéterminée ne devient pas automatiquement un cancer. L’interprétation est intégrée à la taille, aux symptômes, à l’histoire et aux préférences [S3].</p>''','Chercher l’élément qui sépare les hypothèses et change l’action. Le nombre de nodules et la TSH seule ne suffisent pas [S3].'))
S.append(sec(11,'Traitement : une décision partagée et proportionnée','''<p>Un nodule bénin, asymptomatique et concordant avec l’évaluation peut être surveillé. Un traitement vise une question concrète : compression, gêne esthétique importante, récidive kystique, risque ou incertitude diagnostique. Ni découverte fortuite ni augmentation de taille isolée ne donnent une indication uniforme [S3, S4].</p><p>La chirurgie permet une réduction rapide et une analyse histologique. Elle est discutée selon symptômes, extension profonde, cytologie, taille et risque, terrain et préférence. Une lésion limitée à un lobe et un goitre bilatéral ne réclament pas toujours le même geste ; l’équipe explique risque nerveux, risque parathyroïdien et besoin éventuel de substitution. La possibilité de considérer une chirurgie pour un nodule bénin d’au moins4cm ne signifie pas obligation pour tous [S3].</p><p>L’alcoolisation est une option privilégiée pour un kyste pur ou majoritairement kystique symptomatique. Une ablation thermique peut traiter certains nodules solides bénins symptomatiques ; une preuve de bénignité, la concordance, la situation des cordes vocales et les risques de saignement sont vérifiés avant. Dans un goitre multiple, elle vise surtout une cible dominante bien définie ; elle n’est pas automatiquement un traitement de toute la glande [S3].</p><p>Le radioiode est une alternative spécialisée pour certains goitres multinodulaires bénins symptomatiques, notamment si le risque chirurgical est important. Il agit lentement et exige évaluation de fixation, dosimétrie, contre-indications et radioprotection. La lévothyroxine n’est pas un traitement systématique de la maladie nodulaire euthyroïdienne dans le guide européen2023 ; l’indication présente dans une FI doit rester distincte de la décision de traiter [S3–S7].</p>''','Choisir entre surveillance, chirurgie, ablation et radioiode après avoir établi la question, la bénignité suffisamment documentée et les contraintes [S3, S4].'))
S.append(sec(12,'Suivi et pronostic : comparer ce qui est comparable','''<p>La surveillance dépend de la catégorie échographique, de la taille, de la cytologie et des symptômes. Une croissance significative correspond à une augmentation d’au moins20% de deux diamètres avec au moins2mm d’augmentation, ou une hausse de volume supérieure à50%. Ces critères déclenchent une réévaluation ; ils ne constituent pas une preuve de cancer [S3].</p><p>Pour des nodules asymptomatiques non ponctionnés, le guide2023 propose par exemple une réévaluation à trois à cinq ans pour certaines lésions EU-TIRADS2 de plus10mm ou3 de10–20mm, à un an pour4 de moins15mm, et tous les six à douze mois pour5 de moins10mm. Les petits nodules2 ou3 de5–10mm peuvent ne pas nécessiter d’autre contrôle. Les calendriers gardent leurs populations et leurs exceptions ; les preuves sur la durée optimale du suivi sont limitées [S3].</p><p>Une nouvelle gêne, une voix modifiée, une évolution échographique ou un ganglion suspect demande une réévaluation hors calendrier. Après deux cytologies bénignes, une nouvelle biopsie n’est généralement plus nécessaire ; une discordance ou un nouveau problème clinique reste une autre question [S3].</p><p>Après traitement, suivre volume et symptômes, fonction thyroïdienne et effets indésirables. Le radioiode peut conduire à une hypothyroïdie tardive ; la surveillance reste prolongée. Une réduction de volume ne prouve pas la disparition de tout risque ni la guérison d’une maladie indépendante. Le plan de suivi doit être communiqué et compréhensible [S3, S4, S6].</p>''','Comparer mesures, symptômes et images antérieures. Croissance significative signifie réévaluer, pas conclure automatiquement au cancer [S3].'))
S.append(sec(13,'Prévention et situations particulières','''<p>La prévention iodée suisse repose notamment sur le sel enrichi à25mg d’iode par kilogramme. Il s’agit de choisir du sel iodé dans la quantité de sel utilisée, pas d’augmenter les apports en sel. Un complément d’iode ou de sélénium n’est pas recommandé de routine chez une population suffisamment couverte ; une carence documentée se traite dans son contexte et peut modifier le classement étiologique [S3, S8, S11].</p><p>Grossesse et allaitement modifient les besoins et le choix des examens. Le radioiode thérapeutique est contre-indiqué ; échographie et raisonnement spécialisé évitent d’abandonner le bilan d’un nodule suspect. Une substitution de lévothyroxine réellement nécessaire ne doit pas être interrompue parce qu’une grossesse commence. Le conseil OSAV de250µg/j pendant allaitement concerne l’apport total ; ce n’est pas une dose universelle de comprimé à ajouter à tous les aliments [S5, S6, S10].</p><p>Chez l’enfant, les seuils dimensionnels de ponction des adultes ne se transposent pas directement. Le guide européen pédiatrique demande une échographie complète du cou, une analyse des caractéristiques et un parcours spécialisé si suspicion. Les lésions bénignes sont suivies avec nouvelle ponction si évolution suspecte ; bénéfices et risques d’une intervention sont discutés avec la famille [S13].</p><p>Chez la personne âgée ou cardiaque, les conséquences d’un surtraitement hormonal et d’une hyperthyroïdie après charge iodée peuvent être importantes. L’insuffisance rénale peut retarder l’élimination du radioiode ; l’activité et les mesures sont individualisées. L’absence de schéma chiffré rénal ou hépatique ne justifie pas d’en inventer un [S5, S6, S12].</p>''','Prévention nutritionnelle, supplément ciblé et radioiode ont des objectifs différents. Âge, grossesse, cœur et rein modifient les choix [S5, S6, S8, S13].'))
S.append(sec(14,'Critères formels, cadre suisse et pièges d’examen','''<div class="alert"><b>Formulation du diagnostic.</b> Décrire goitre diffus, nodule unique ou goitre multinodulaire, préciser l’état fonctionnel, les symptômes et les éléments de risque, puis vérifier la maladie causale et les exclusions. Une TSH normale n’est pas un critère de bénignité ; une cytologie non diagnostique n’est pas une preuve de tissu sain [S1–S3].</div><div class="key"><b>Paramètres utiles.</b> Chez l’adulte, ponction EU-TIRADS3 si diamètre>20mm,4 si>15mm,5 si>10mm ; ganglion suspect ou extension peuvent modifier l’indication indépendamment du score. Croissance :20% dans deux diamètres avec2mm minimum, ou volume>50%. Sel iodé suisse25mg/kg : concentration du sel, pas dose quotidienne de supplément [S3, S8].</div><p>En Suisse, le radioiode relève d’une structure autorisée et d’une planification individuelle. La directive OFSP2025 prévoit pour l’iode131 un traitement résidentiel dès200MBq, une durée minimale de48heures et un débit de dose inférieur à10µSv/h à un mètre comme critère de sortie supplémentaire. Des exceptions ambulatoires entre200et400MBq requièrent une autorisation préalable ; ces chiffres sont des critères de radioprotection et non une dose à prescrire à tout goitre [S7].</p><p>Aucune obligation générale propre E04 de déclaration, de mesure Suva, d’invalidité ou de restriction de conduite n’a été établie dans ces lectures. La FI Curium indique une influence nulle ou négligeable sur la conduite, sans études correspondantes ; l’état réel et les autres traitements restent évalués. Le code ne promet ni remboursement automatique, ni disponibilité actuelle d’un produit, ni accès à toute technique [S1, S6, S7].</p><p>Pour l’examen, expliquer pourquoi « non toxique » ne signifie pas bénin, pourquoi le plus gros nodule n’est pas toujours la meilleure cible, et pourquoi un seuil de ponction n’est pas un seuil de chirurgie. Justifier le niveau de soins, les limites du test et le suivi. Audit différé — revue par intelligence artificielle, distincte d’une validation médicale humaine [S3, S16].</p>''','Le diagnostic doit être descriptif, fonctionnel et raisonné. Les nombres gardent leur source, leur population et leur objectif [S1–S3, S7].'))
E=[]
us_table=table(['Catégorie adulte','Description résumée','Ponction dans le guide2023'],[['EU-TIRADS2','Kyste pur ou entièrement spongiforme.','Non, sauf projet thérapeutique particulier.'],['EU-TIRADS3','Iso/hyperéchogène sans signe de forte suspicion.','Si diamètre>20mm.'],['EU-TIRADS4','Modérément hypoéchogène sans signe de forte suspicion.','Si diamètre>15mm.'],['EU-TIRADS5','Au moins un signe très suspect : forme ou marges irrégulières, microcalcifications, hypoechogénicité marquée.','Si diamètre>10mm ; plus petit selon ganglion/extension/contexte.']])
E.append(sec('e-1','Échographie : risque, dimensions et ganglions',us_table+'''<p>Ces seuils sont strictement « supérieur à », et s’appliquent aux adultes. Un ganglion pathologique ou une suspicion d’extension extrathyroïdienne peut justifier une ponction indépendamment du score. Pour un nodule de5–10mm très suspect, cette discussion est notamment indiquée si ganglions suspects ou extension ; la proximité de la trachée ou d’un nerf importe aussi dans la décision intégrée [S3].</p><p>Le compte rendu décrit les trois dimensions, composition, échogénicité, forme, marges, calcifications et rapports. En cas de nodules multiples, repérer et identifier ceux qui nécessitent un suivi ou un prélèvement. L’échographie n’exclut pas à elle seule toute forme de cancer : les systèmes ont surtout été développés pour certaines formes papillaires et sont moins performants pour d’autres tumeurs [S3].</p><p>Les pourcentages de risque sont dépendants de la population et du recrutement. Il serait incorrect d’annoncer le risque d’une série opérée comme la probabilité personnelle de toute personne ayant le même score. Le score structure le raisonnement, sans remplacer la clinique ni la cytologie indiquée [S3].</p>''','Rapporter le score avec les dimensions et le cou entier. Le ganglion ou l’extension peut changer la décision avant un seuil dimensionnel [S3].'))
E.append(sec('e-2','Biologie et scintigraphie : lire la fonction','''<p>La TSH s’interprète avec l’intervalle du laboratoire et le contexte. Une valeur sous la limite normale appelle un dosage hormonal et, selon le bilan, une scintigraphie. Une TSH dans la norme ne renseigne pas directement sur la nature histologique d’un nodule. La biotine, des médicaments et une maladie intercurrente peuvent compliquer l’interprétation ; documenter avant de conclure à une nouvelle maladie [S3, S5].</p><p>La thyroxine et la triiodothyronine circulent largement liées à des protéines ; les fractions libres utilisées en clinique ne se confondent pas avec les concentrations totales. Les mesures gardent leur méthode, leurs unités et leurs références, surtout en grossesse. Ne pas convertir un nombre sans savoir s’il s’agit de fraction libre ou totale [S3, S14].</p><p>La scintigraphie montre la répartition de captation, pas une photographie de toutes les cellules. Elle distingue des zones hyperfonctionnelles et hypofonctionnelles et aide à sélectionner les prélèvements et l’éligibilité au radioiode. Un contraste iodé récent peut réduire la fixation et rendre l’examen trompeur ; une image peu fixante doit être située dans l’histoire d’exposition [S3, S12].</p><p>La calcitonine peut être utile devant une suspicion de cancer médullaire, une histoire familiale pertinente, une cytologie indéterminée ou avant certains traitements. La thyroglobuline sérique n’est pas un test initial fiable de bénignité. Aucun dosage ne remplace une analyse du nodule et du contexte [S3].</p>''','La fonction biologique et la fonction régionale ne sont pas la cytologie. Un résultat doit garder sa méthode et son contexte [S3, S12, S14].'))
cyto_table=table(['Résultat','Interprétation','Étape possible selon contexte'],[['BethesdaI','Non diagnostique : cellules insuffisantes ou prélèvement inadéquat.','Répéter ponction ; autres prélèvements/discussion si échecs persistants.'],['BethesdaII','Bénin en cytologie.','Confronter à échographie ; répéter si discordance très suspecte.'],['BethesdaIII','Atypie de signification indéterminée.','Répéter ponction puis surveillance/analyses/discussion selon risque.'],['BethesdaIV','Néoplasie folliculaire ou suspicion de telle néoplasie.','Discussion spécialisée souvent chirurgicale, surveillance possible dans cas sélectionnés.'],['BethesdaV–VI','Suspect de malignité ou malin.','Parcours tumoral spécialisé ; le type compte, notamment si lymphome suspect.']])
E.append(sec('e-3','Cytologie : ni score de fonction ni verdict universel',cyto_table+'''<p>La cytologie utilise une classification normalisée et une estimation locale du risque. Ce tableau reprend les catégories qualitatives utilisées par le guide européen2023 ; son tableau numérique se fondait sur l’édition2017 de Bethesda, et la troisième édition est parue après la première version du manuscrit. Aucun pourcentage ancien n’est présenté ici comme valeur absolue de2026 [S3].</p><p>Une lésion folliculaire peut nécessiter une analyse tissulaire pour distinguer certaines entités. Les tests moléculaires sont des outils complémentaires sélectionnés ; des anomalies comme une mutation RAS peuvent aussi se rencontrer dans des lésions bénignes. Leurs performances dépendent de la validation et du risque préalable ; un résultat commercial ne garantit ni diagnostic individuel ni remboursement suisse [S3].</p>''','Un prélèvement insuffisant ne rassure pas. Une atypie n’est pas synonyme de cancer ; la concordance et le contexte guident la suite [S3].'))
E.append(sec('e-4','Comparer la croissance : un calcul explicite','''<p>Pour un diamètre, la variation relative est : (nouvelle mesure−ancienne mesure)÷ancienne mesure×100. Exemple pédagogique fictif : passer de20à24mm donne (24−20)÷20×100=20%, soit4mm. Cela ne suffit pas seul au critère européen qui demande cette augmentation dans au moins deux diamètres, avec2mm minimum, ou un volume augmenté de plus50% [S3].</p><p>Les plans et la technique doivent être comparables. Une différence de mesure n’est pas nécessairement une modification biologique ; un changement kystique ou un saignement peut aussi faire varier le volume. L’état clinique et les caractéristiques échographiques comptent avec les nombres. Le seuil de croissance vise à décider d’une réévaluation, pas à prédire seul la malignité [S3].</p><p>Avant d’appliquer une règle de suivi, vérifier âge, score, taille, cytologie éventuelle et symptômes. Les adultes avec deux prélèvements bénins concordants et les enfants avec un nodule suspect ne relèvent pas d’un tableau unique. Les calendriers ne doivent pas retarder une évaluation si une nouvelle gêne apparaît [S3, S13].</p>''','Un seul diamètre à20% ne satisfait pas à lui seul le critère complet. Calculer, puis interpréter [S3].'))
quizzes=[('Une TSH normale devant un goitre signifie…',[('La fonction est actuellement compatible avec une normalité, mais le risque tumoral reste à évaluer.',1),('Le cancer et la compression sont exclus.',0)],'La fonction et la structure sont distinctes ; évaluer symptômes, échographie et prélèvement indiqué [S3, S4].'),('Un nodule adulte EU-TIRADS4 de15mm exactement, sans autre signe, franchit-il le seuil dimensionnel de ponction du guide2023 ?',[('Non : le seuil est strictement supérieur à15mm ; considérer tout le contexte.',1),('Oui, le seuil est automatiquement au moins15mm.',0)],'Le comparateur strict doit être conservé. Ganglion suspect, extension et contexte peuvent modifier la décision [S3].'),('Une FI mentionne75–200µg/j de lévothyroxine pour goitre bénin euthyroïdien. Faut-il traiter tout nodule euthyroïdien ?',[('Non ; la FI décrit une indication et une dose, tandis que le guide2023 déconseille le traitement systématique de la maladie nodulaire euthyroïdienne.',1),('Oui ; toute indication de FI rend le traitement obligatoire.',0)],'Une indication réglementaire n’est pas une recommandation de traiter toute personne ; bénéfice et risques doivent être évalués [S3, S5].'),('Un goitre provoque une compression respiratoire qui doit être levée rapidement. Choisir le radioiode seul immédiatement ?',[('Non ; organiser une évaluation urgente et une décompression adaptée, car son effet est retardé et un gonflement transitoire est possible.',1),('Oui ; le radioiode décomprime immédiatement.',0)],'Le besoin de résolution rapide de la compression est une contre-indication au radioiode dans le guide spécialisé [S4, S6].')]
for i,(question,answers,explanation) in enumerate(quizzes,1):E.append('<div class="quiz"><b>Question'+str(i)+'. '+question+'</b><div>'+''.join('<button data-ok="'+str(ok)+'">'+ans+'</button>' for ans,ok in answers)+'</div><div class="fb" hidden>'+explanation+'</div></div>')
# One published human original, twice; logical diagrams do not depict anatomy.
asset=R/'assets/img/e04/alpha/codex/thyroid-openstax2013.jpg';asset.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(C/'normal-thyroid-openstax2013.jpg',asset);(D/'figures').mkdir(exist_ok=True);shutil.copyfile(asset,D/'figures/thyroid-openstax2013.jpg')
def humanfig():return '''<figure><div data-e04-frame="1"><img src="assets/img/e04/alpha/codex/thyroid-openstax2013.jpg" alt="Planche humaine normale : vues antérieure et postérieure de la thyroïde puis micrographie de follicules ; quatre repères français explicités." loading="eager"><span data-e04-marker="1" data-e04-pin="1">1</span><span data-e04-marker="1" data-e04-pin="2">2</span><span data-e04-marker="1" data-e04-pin="3">3</span><span data-e04-marker="1" data-e04-pin="4">4</span></div><figcaption>OpenStax College, Connexions,19juin2013 ; micrographie fournie par les Regents of University of Michigan Medical School©2012. <a data-reference-source="1" href="https://commons.wikimedia.org/wiki/File:1811_The_Thyroid_Gland.jpg" target="_blank" rel="noopener">Original1811, Creative Commons Attribution3.0</a>. Pixels inchangés ; repères superposés :1isthme devant la trachée,2trachée,3parathyroïde postérieure,4colloïde d’un follicule. Planche normale, pas goitre E04 ni cytologie de risque. Un même original utilisé deux fois. Microscopie optique1332× dans la légende du manuel, pas calibration de l’écran ; coloration non établie. Les labels anglais sont complétés par la légende française [S14, S15].</figcaption></figure>'''
units={}
semio=[('normal','Normal : séparer volume et fonction','La thyroïde est un organe cervical organisé en follicules. La fonction hormonale est régulée, tandis que l’examen et l’échographie décrivent la structure et le volume. Un dosage normal ne décrit donc pas toutes les dimensions de l’organe. La palpation, les rapports anatomiques et le contexte complètent le bilan ; aucune image normale ne démontre la bénignité d’une masse individuelle [S3, S14].'),('signs','Signes : masse, gêne et évolution','Un gonflement cervical, un contour irrégulier, une gêne à avaler, une dyspnée ou une voix modifiée sont des observations à dater et à décrire. Le mot non toxique ne les annule pas. Une lésion peut être palpable ou découverte par imagerie ; l’absence de nodule palpable ne suffit pas à exclure une lésion profonde ou petite. Ni douleur ni absence de douleur ne tranche seule la nature [S3, S4].'),('mechanisms','Mécanismes : du tissu au retentissement','Prolifération, colloïde et composantes kystiques peuvent accroître le volume alors que la production hormonale reste équilibrée. Une croissance vers la trachée ou l’œsophage peut produire une gêne mécanique. Une autonomie fonctionnelle peut se développer ou être révélée par une charge iodée ; ce mécanisme se distingue d’une compression et d’une transformation tumorale, qui ne sont pas des étapes obligatoires du même processus [S3, S4, S12].'),('examination','Examen : observer et palper avec méthode','Évaluer respiration et voix, inspecter le cou, puis palper doucement lobes, isthme et aires ganglionnaires. Décrire siège, mobilité à la déglutition, douleur, consistance et limites accessibles. La mobilité suggère une origine, sans prouver la bénignité. Une suspicion d’extension rétrosternale ou un symptôme compressif appelle une exploration ciblée plutôt qu’une conclusion fondée sur la seule partie palpable [S3, S4, S14, S16].'),('interpretation','Interprétation : raisonner par questions','La TSH renseigne sur le contrôle fonctionnel, l’échographie sur les caractéristiques et les ganglions, la scintigraphie sur la fonction régionale et la cytologie sur les cellules prélevées. Une discordance mérite une analyse. Un score élevé n’est pas un résultat histologique ; un prélèvement insuffisant n’est pas bénin. Les normes biologiques et les probabilités dépendent des méthodes et des populations [S3, S5].'),('differentials','Différentiels : garder la cause ouverte','Comparer goitre bénin non toxique, maladie par carence iodée, thyroïdite, goitre avec hyperthyroïdie, tumeur et masse d’autre origine. L’élément discriminant peut être fonctionnel, échographique, cytologique ou étiologique. Un diagnostic causal établi peut modifier le code. Des nodules multiples ne protègent pas du cancer et un nodule unique ne l’affirme pas ; le choix du prélèvement repose sur le risque, pas seulement sur le nombre [S1–S3].'),('urgency','Urgence : la respiration avant le calendrier','Stridor ou détresse respiratoire demandent une évaluation urgente adaptée aux voies aériennes. Une croissance rapide, un ganglion suspect ou une voix nouvellement modifiée accélèrent l’analyse spécialisée selon retentissement. Le radioiode n’agit pas immédiatement et peut faire gonfler transitoirement la glande ; il ne remplace pas une décompression rapide quand elle est nécessaire. Le délai clinique ne se déduit pas d’un code [S3, S4, S6].'),('limits','Limites : mesures, seuils et populations','La palpation et l’échographie dépendent de l’examinateur ; les systèmes échographiques ont des limites selon le type tumoral. Les seuils adultes ne se transposent pas directement à l’enfant. Un changement de mesure ne représente pas nécessairement une croissance biologique. Les calendriers de suivi ont une certitude limitée, et une TSH initialement normale n’exclut pas une dysfonction après contraste iodé sur terrain autonome [S3, S12, S13].'),('sources','Sources lues : niveaux et décisions','La classification suisse locale et les notes allemandes2024 encadrent le code. Le guide européen2023 fonde le bilan et les choix adultes ; le guide pédiatrique2022 garde son périmètre. Les informations professionnelles suisses datées fondent les médicaments, et la directive OFSP2025 la radioprotection. Les liens renvoient aux sources réellement lues, sans confondre notice réglementaire, formation et preuve de bénéfice [S1–S7, S13, S16].')]
sem='<section class="ilot" id="e04-semio-cours"><h3>Pour la leçon : quelle est la sémiologie fondamentale et analytique ?</h3>'
for k,title,txt in semio:sem+=f'<section class="ilot" id="e04-semio-{k}" data-semiology="{k}"><h3>{title}</h3><p>{txt}</p></section>'
sem+=logical('Signe observé','Mécanisme et question','Examen puis décision','La démarche ne transforme pas un signe en diagnostic automatique [S3, S4].');sem+='<div class="key"><b>À retenir.</b> Décrire le signe, expliquer un mécanisme plausible, choisir le test qui répond à la question puis décider selon la gravité et le risque [S3, S4].</div></section>';units['semio']=sem
units['anat']=sec('s-anat-cours','Anatomie : rapports qui expliquent les symptômes','''<p>La thyroïde normale comprend deux lobes latéraux et un isthme en avant de la trachée, sous le larynx. Les parathyroïdes se trouvent principalement sur la face postérieure. Les vaisseaux et les structures laryngées sont proches, sans constituer les mêmes tissus. La planche présente une vue antérieure et une vue postérieure : reconnaître l’orientation évite de confondre les rapports visibles et les régions profondes [S14, S15].</p><p>Une augmentation de volume peut être diffuse ou faite de nodules. La surface accessible à la palpation ne représente pas nécessairement tout le développement de la glande ; une partie peut se prolonger derrière le sternum. La présence d’une fonction normale ne modifie pas ces rapports. Un organe qui produit une quantité appropriée d’hormones peut malgré tout prendre de la place et exercer une pression [S3, S4].</p><p>La trachée conduit l’air et l’œsophage permet la déglutition ; leur proximité explique pourquoi dyspnée et dysphagie sont des questions pertinentes. Une voix modifiée conduit à évaluer le larynx et les structures nerveuses dans le contexte. Ces symptômes n’identifient pas seuls le tissu causal et ne prouvent pas une invasion cancéreuse, mais demandent une explication proportionnée au retentissement [S3, S4].</p><p>L’échographie examine la glande et les ganglions du cou. Une extension sous-sternale peut justifier une imagerie en coupe afin d’étudier la trachée, le médiastin supérieur et les rapports profonds. Le choix du contraste tient compte du contexte iodé et fonctionnel ; il n’est pas un détail interchangeable avant une scintigraphie ou un radioiode [S3, S12].</p><p>Pour le traitement, ces rapports expliquent la nécessité d’une équipe expérimentée en chirurgie et la vérification des cordes vocales avant certaines ablations. Le geste est choisi selon les territoires atteints et la question clinique. La planche normale aide à comprendre le risque anatomique ; elle ne montre ni la compression de la patiente fictive ni une lésion de nerf, et ne permet pas de mesurer un goitre individuel [S3, S14].</p>'''+humanfig(),'Les rapports expliquent les symptômes mécaniques et les précautions du geste, indépendamment de la fonction hormonale [S3, S4, S14].')
units['histo']=sec('s-histo-cours','Histologie : follicule, colloïde et limites du prélèvement','''<p>Le follicule thyroïdien normal est une unité constituée de cellules épithéliales autour d’une lumière contenant de la colloïde. La thyroglobuline y sert de support à la synthèse et au stockage des hormones. Les cellules folliculaires ne doivent pas être confondues avec les cellules parafolliculaires, ou cellules C, associées à la calcitonine. La micrographie de cette planche représente le tissu normal ; elle n’est pas une cytoponction d’un nodule ni une preuve de bénignité [S14, S15].</p><p>Dans une maladie nodulaire, architecture, quantité de colloïde, cellules et remaniements peuvent varier selon les zones. Un aspect kystique décrit une composition, sans résumer à lui seul tout le risque. Les images échographiques utilisent une autre échelle et d’autres propriétés du tissu : une zone sombre à l’échographie ne s’identifie pas simplement à la couleur d’une structure sur une lame [S3, S14].</p><p>La cytoponction recueille des cellules et du matériel. Sa qualité dépend du prélèvement, de la cible et de l’analyse. Une catégorie non diagnostique signifie que l’échantillon ne permet pas de conclure ; elle ne prouve pas que le nodule est normal. Une catégorie bénigne doit rester concordante avec l’échographie et l’évolution. En cas de discordance très suspecte, la réévaluation protège contre une rassurance fondée sur un résultat isolé [S3].</p><p>Certains diagnostics folliculaires demandent une analyse tissulaire complémentaire ; la catégorie cytologique n’est donc pas une simple étiquette oui/non. La chirurgie peut avoir un objectif diagnostique lorsque l’incertitude et le contexte le justifient. Des prélèvements plus larges peuvent aussi être discutés dans certaines situations, notamment si un lymphome ou une autre histologie particulière est suspecté [S3].</p><p>Les immunomarquages et tests moléculaires ne remplacent pas systématiquement la morphologie. Le guide européen insiste sur les performances locales et les validations ; une anomalie moléculaire peut aussi exister dans une lésion bénigne. Comprendre les limites du matériau évite d’annoncer un cancer sur un terme indéterminé ou de promettre qu’un prélèvement incomplet a tout exclu [S3].</p>'''+humanfig(),'La cytologie étudie ce qui a été prélevé. Interpréter sa qualité et sa concordance avant de décider [S3, S14].')
units['physio']=sec('s-physio-cours','Physiologie : rétrocontrôle et autonomie régionale','''<p>Le fonctionnement normal associe une commande hypophysaire et la réponse des cellules folliculaires. La thyréostimuline stimule la synthèse et la libération des hormones ; lorsque les hormones augmentent, le rétrocontrôle réduit la stimulation. La thyroxine et la triiodothyronine participent aux fonctions métaboliques et au développement. Le système règle une production, mais il n’assure pas que chaque région ait une architecture ou une taille identiques [S14].</p><p>Un goitre non toxique peut maintenir une production globale dans l’intervalle attendu. La présence d’un volume important ne signifie pas nécessairement une production excessive ; inversement, une petite région autonome peut modifier le contrôle global. L’évaluation garde donc des axes distincts : structure, sécrétion et risque de nature du tissu. La TSH donne un signal fonctionnel utile mais ne visualise aucun nodule [S3, S4].</p><p>Dans une autonomie, une région fonctionne moins sous le contrôle habituel. La scintigraphie renseigne sur la répartition relative de la captation et peut identifier cette hétérogénéité. Dans des régions ayant connu une carence iodée, des zones hyperfonctionnelles peuvent être présentes alors que la TSH est encore normale ; l’indication de scintigraphie se discute donc selon l’ensemble clinique et l’objectif [S3].</p><p>Une charge iodée importante peut fournir davantage de substrat à un tissu autonome et révéler une hyperthyroïdie. Le contraste peut également produire des changements transitoires des dosages et réduire la fixation des isotopes. Les conséquences sont particulièrement pertinentes chez les personnes âgées ou cardiaques, dont les signes peuvent être discrets. Une valeur normale avant contraste ne garantit pas que la fonction restera normale [S12].</p><p>Cette physiologie éclaire le traitement : on ne donne pas automatiquement une hormone supplémentaire à une glande dont la fonction est normale. L’effet recherché doit être confronté au risque de surtraitement, notamment cardiaque et osseux. Une vraie insuffisance demandant substitution reste une autre indication ; sa prise en charge ne se déduit pas d’une stratégie ancienne de réduction de volume [S3, S5].</p>'''+logical('Commande et rétrocontrôle','Production globale et régions différentes','Bilan fonctionnel contextualisé','Organisation du raisonnement physiologique, sans prétendre que toute autonomie devient toxique [S3, S12, S14].'),'Euthyroïdie globale et hétérogénéité régionale peuvent coexister. La fonction ne révèle pas toute la structure [S3, S12].')
units['bioch']=sec('s-bioch-cours','Biochimie : iode, hormones et médicaments distincts','''<p>L’iodure est un substrat de la synthèse hormonale. Il est capté par les cellules folliculaires puis incorporé à des résidus de tyrosine de la thyroglobuline ; le couplage permet de former les hormones contenant trois ou quatre atomes d’iode. Leur libération implique la reprise et la dégradation du support protéique. Ces étapes décrivent une chaîne cellulaire organisée, pas la conversion directe de tout aliment iodé en un effet immédiat sur le volume du cou [S14].</p><p>Dans le sang, les hormones circulent surtout liées à des protéines. La fraction libre et la concentration totale ne répondent donc pas exactement à la même mesure. Le laboratoire précise méthode, unités et intervalle ; certains traitements ou suppléments peuvent perturber l’analyse. La biotine signalée dans la FI doit être documentée et discutée avec le laboratoire, sans inventer un délai d’arrêt unique pour tous les produits et toutes les méthodes [S5, S14].</p><p>La lévothyroxine apporte une hormone, tandis que l’iode stable apporte un substrat et que l’iode radioactif délivre une irradiation à un tissu qui le fixe. Ces trois interventions n’ont ni la même unité, ni la même indication, ni le même mécanisme. Microgrammes d’hormone, milligrammes d’iode par kilogramme de sel et mégabecquerels d’activité ne sont pas des quantités interchangeables [S5, S6, S8].</p><p>La fixation du radioiode dépend du volume, de la fonction régionale, des apports iodés et de la clairance. Un produit de contraste ou l’amiodarone peut modifier cette fixation ; le service spécialisé établit les conditions et le calendrier. Une gélule dont la présentation couvre une large plage d’activité n’est pas une prescription standard pour tout goitre. L’insuffisance rénale peut accroître l’exposition en retardant l’élimination [S6, S12].</p><p>Enfin, corriger un déficit nutritionnel documenté et traiter un nodule bénin symptomatique sont des objectifs différents. Le guide européen ne recommande pas d’ajouter iode ou sélénium à toute maladie nodulaire lorsque les apports sont suffisants. Une source alimentaire ou un supplément ne se choisit pas sur l’espoir de faire disparaître automatiquement une lésion structurale [S3, S8, S11].</p>'''+logical('Substrat iodé','Synthèse et transport hormonal','Tests et traitements de buts différents','Schéma conceptuel, sans anatomie ; les branches ne sont pas une équivalence de doses [S5, S6, S14].'),'Distinguer le substrat, l’hormone et l’activité radioactive avant de lire un chiffre ou de calculer une prise [S5, S6, S8].')
units['gene']=sec('s-gene-cours','Génétique et immunologie : terrain, nodule et preuve','''<p>Les cellules d’un tissu normal contrôlent leur fonctionnement et leur renouvellement par des programmes moléculaires. Le système immunitaire et les anticorps peuvent aussi modifier l’environnement thyroïdien. La distinction entre une anomalie du tissu, une réponse auto-immune et une modification de fonction évite de faire du mot goitre une cause unique. L’évaluation initiale ne repose pas sur un séquençage général mais sur histoire, fonction, échographie et prélèvement indiqué [S3, S14].</p><p>Des nodules peuvent porter des modifications somatiques qui ne sont pas présentes dans toutes les cellules du corps. Le guide européen rapporte que certaines mutations RAS et certains remaniements peuvent aussi être observés dans des lésions bénignes. Leur détection ne constitue donc pas automatiquement une preuve de cancer ni une indication de chirurgie totale. Une analyse moléculaire complète la morphologie et le risque préalable selon ses performances réellement validées [S3].</p><p>Une prédisposition germinale est une autre situation. Chez l’enfant et dans des familles ou phénotypes évocateurs, les syndromes liés à DICER1 ou à PTEN peuvent associer goitre multinodulaire et autres lésions. L’histoire personnelle, familiale et les manifestations associées guident l’orientation spécialisée. Cela ne signifie pas que la majorité des adultes avec E04 ont une maladie mendélienne, ni qu’un nodule multiple isolé demande tous les tests génétiques possibles [S13].</p><p>Du côté immunologique, une thyroïdite peut modifier l’architecture et produire des zones ressemblant à des nodules. Si la TSH est augmentée, les anticorps antithyroperoxydase peuvent aider à documenter ce contexte ; d’autres anticorps sont discutés si la suspicion persiste. Un anticorps positif ne classe pas à lui seul chaque nodule et ne remplace pas l’analyse d’un signe échographique suspect [S3].</p><p>Pour la conduite, retenir la différence entre risque, association et preuve. Un test doit répondre à une question susceptible de modifier la décision. Les performances commerciales et les résultats de centres sélectionnés ne garantissent pas les mêmes valeurs prédictives ailleurs. Le patient doit comprendre ce qui est appris, ce qui reste incertain et quelles alternatives de surveillance ou d’analyse existent avant une décision irréversible [S3, S13].</p>'''+logical('Terrain familial ou contexte immune','Caractéristiques du tissu et du nodule','Analyse ciblée, puis décision intégrée','Les niveaux se complètent ; aucune mutation unique ne définit tous les goitres E04 [S3, S13].'),'Germinal, somatique et auto-immun ne sont pas synonymes. Un résultat moléculaire reste lié à sa validation et au contexte [S3, S13].')
bridges={'semio':'S3, S4','anat':'S3, S14','histo':'S3, S14','physio':'S3, S5, S12','bioch':'S3, S5, S6, S14','gene':'S3, S13'}
for k,ss in bridges.items():units[k]+='<div class="key"><b>Science → clinique.</b> Le fonctionnement normal explique un signe possible sans prouver sa cause individuelle. <b>Science → examen.</b> Choisir la mesure qui répond à la question et confronter ses limites. <b>Science → traitement.</b> Adapter l’intervention à la fonction, au risque et au retentissement, après discussion ['+ss+'].</div>'
sc='<div class="panel" id="pS" hidden><div class="sci-bar ui" role="tablist">'
for i,(k,label) in enumerate([('semio','Sémiologie fondamentale et analytique'),('anat','Anatomie'),('histo','Histologie'),('physio','Physiologie'),('bioch','Biochimie'),('gene','Génétique et immunologie')]):sc+=f'<button id="e04-tab-{k}" role="tab" aria-controls="e04-s-{k}" aria-selected="{str(i==0).lower()}" data-s="e04-s-{k}">{label}</button>'
sc+='</div>'
for i,(k,body) in enumerate(units.items()):sc+=f'<div class="sci" id="e04-s-{k}" role="tabpanel" aria-labelledby="e04-tab-{k}"'+(' hidden' if i else '')+'>'+body+'</div>'
sc+='</div>'
P=[]
P.append(sec('p-1','Avant un médicament : clarifier l’objectif','''<p>Traiter un déficit hormonal, réduire un volume bénin et prévenir une conséquence de charge iodée ne sont pas le même objectif. Un nodule euthyroïdien asymptomatique peut être surveillé ; l’existence d’une ligne de posologie dans une FI ne rend pas le traitement nécessaire pour toute personne ayant le même code [S3, S5].</p><p>Le guide européen2023 déconseille les hormones thyroïdiennes dans la maladie nodulaire euthyroïdienne. Le guide de médecine nucléaire2023 discute encore une sélection de jeunes personnes avec goitre modeste pour la lévothyroxine ; ce périmètre et cette position ne doivent pas être transformés en consensus contraire au guide nodulaire. La décision individuelle expose la population, l’objectif et les risques [S3, S4].</p><p>Les thyréostatiques ne traitent pas automatiquement un goitre sans hyperthyroïdie. Une hyperthyroïdie sur autonomie ou après contraste ouvre un autre parcours ; une éventuelle prophylaxie est spécialisée et non recommandée chez tout patient à risque. Aucune posologie de carbimazole n’est présentée ici comme dose de radioiode [S3, S12].</p>''','L’indication précède la dose. Distinguer bénéfice attendu, information réglementaire et recommandation clinique [S3–S5].'))
lt4_table=table(['Situation, FI février2023','Repère de dose/prise','Limite'],[['Goitre bénin euthyroïdien, adulte','75–200µg une fois/jour, oral, selon indication et réponse.','Dose de FI, pas recommandation de traiter toute maladie nodulaire euthyroïdienne.'],['Prise du comprimé','À jeun, au moins30min avant petit-déjeuner, avec eau.','Horaire et interactions peuvent modifier absorption.'],['Patient âgé/cardiaque ou hypothyroïdie sévère ancienne si substitution indiquée','Début bas, notamment25µg/j puis augmentation prudente.','Pas dose automatique de réduction E04 ; suivi clinique et biologique.'],['Rein/foie','Pharmacocinétique non étudiée selon FI.','Pas adaptation chiffrée universelle inventée.'],['Enfant','Dose dépend indication et âge ; prise en charge adaptée.','Les doses d’hypothyroïdie congénitale ne sont pas un schéma de goitre E04.']])
P.append(sec('p-2','Euthyrox : formulation, dose et risque de surtraitement',lt4_table+'''<p>La FI lue est celle d’Euthyrox, comprimés de lévothyroxine sodique de25à200µg, mise à jour février2023, référence produit GTIN7680549490017. Une dose de75µg correspond à0,075mg : ce simple changement d’unité ne transforme pas une dose en indication. Confondre microgramme et milligramme produit un facteur mille [S5].</p><p>La plage75–200µg/j figure pour le goitre bénin euthyroïdien et la prévention de récidive, sur des mois à des années selon la situation. Elle reste confrontée au guide européen2023 qui ne recommande pas le traitement systématique de la maladie nodulaire euthyroïdienne. Les doses de substitution de l’hypothyroïdie relèvent d’une autre indication et ne sont pas ajoutées à cette plage [S3, S5].</p><p>Rechercher autonomie et maladies cardiaques avant une décision hormonale. Les contre-indications du produit comprennent notamment certaines affections cardiaques aiguës ou non stabilisées, une insuffisance surrénalienne/hypophysaire non traitée et une hyperthyroïdie hors situations précisées dans la FI. Une dose excessive peut provoquer palpitations, tachycardie et arythmie ; la suppression prolongée expose aussi l’os. Le suivi doit rechercher le bénéfice comme le surtraitement [S3, S5].</p>''','Une quantité exacte n’est sûre qu’avec l’indication, l’unité et le suivi appropriés. Ne pas supprimer la TSH de routine pour un nodule euthyroïdien [S3, S5].'))
interaction_table=table(['Produit/contexte','FI Euthyrox','Décision'],[['Résines échangeuses d’ions','Les administrer4–5h après lévothyroxine.','Éviter absorption diminuée.'],['Calcium, fer, médicaments contenant aluminium','Lévothyroxine au moins2h avant.','Ne pas remplacer ce délai de FI par un intervalle universel inventé.'],['Inhibiteur de pompe à protons, soja ou modification d’alimentation','Absorption ou besoin peuvent changer.','Contrôle biologique/clinique et dose réévaluée.'],['Anticoagulants et antidiabétiques','Effet thérapeutique peut être modifié.','Surveillance adaptée au médicament.'],['Biotine','Interférence possible avec analyses thyroïdiennes.','Informer laboratoire/prescripteur ; stratégie selon méthode.']])
P.append(sec('p-3','Lévothyroxine : interactions, grossesse et allaitement',interaction_table+'''<p>La liste des médicaments et compléments doit être concrète : produit, horaire, dose, changement récent. Une TSH différente après un nouveau produit peut refléter une absorption modifiée ou une interférence d’analyse ; l’augmentation immédiate de dose n’est pas la seule explication possible. L’interprétation prend aussi en compte prise réelle et indication initiale [S5].</p><p>Une substitution réellement nécessaire est poursuivie pendant grossesse et allaitement avec surveillance spécialisée ; les besoins peuvent augmenter en grossesse. Après accouchement, la FI prévoit retour à la dose préconceptionnelle et contrôle de TSH après six à huit semaines selon le contexte. Cela ne crée pas une indication de commencer une suppression hormonale pour chaque goitre euthyroïdien [S3, S5].</p><p>L’association de lévothyroxine avec un thyréostatique dans une stratégie de blocage-substitution est contre-indiquée pendant grossesse selon cette FI. La compatibilité de la substitution ne signifie donc pas que toute combinaison ou tout objectif thérapeutique soit compatible. Les symptômes et résultats sont suivis sans arrêt autonome d’un traitement nécessaire [S5].</p>''','Vérifier l’absorption et le contexte avant de changer une dose. La substitution nécessaire pendant grossesse est distincte d’une suppression de routine [S3, S5].'))
radio_table=table(['Curium, FI juillet2022','Ce qui est établi','Ce qui ne se déduit pas'],[['Produit','Sodium iodide (I-131) capsule T Curium, oral ; indication inclut goitre euthyroïdien.','Pas carbimazole ni capsule diagnostique d’iode123.'],['Présentation','37–7400MBq par capsule à la date de calibration.','Pas plage prescrite à toute personne E04.'],['Activité thérapeutique','Individualisée selon diagnostic, volume, fixation et clairance ; effet en semaines.','Pas dose fixe universelle ni traitement immédiat d’une compression.'],['Fonction rénale','Élimination retardée, exposition potentiellement accrue, attention/ajustement individualisés.','Pas formule de réduction copiée sans dosimétrie.'],['Enfant/adolescent','Bénéfice/risque soigneusement évalué, activité adaptée ou dosimétrie individuelle.','Pas simple transposition de l’adulte ni indication usuelle de tout nodule pédiatrique.']])
P.append(sec('p-4','Radioiode : produit exact et dosimétrie',radio_table+'''<p>Le radioiode peut être choisi pour certains goitres bénins symptomatiques après bilan. Le guide spécialisé rapporte dans des populations sélectionnées une réduction de volume d’environ40–50% à un an, variable et non immédiate. Un besoin de décompression trachéale rapide ou une suspicion de cancer empêche de le traiter simplement comme un goitre bénin [S3, S4].</p><p>La dosimétrie met en relation activité administrée, volume cible, fixation et durée de rétention ; mégabecquerel décrit une activité et gray une dose absorbée. La FI précise ces paramètres et renvoie au guide spécialisé. Le service calcule et documente l’activité, la mesure avant utilisation et vérifie que les conditions du test et du traitement concordent. Aucune valeur de présentation ni dose d’ablation d’un cancer n’est convertie en dose E04 [S6, S7].</p><p>La stimulation par thyréostimuline recombinante pour augmenter la fixation d’un goitre non toxique est hors indication dans le guide européen2023 et n’est pas un adjuvant routinier. Elle peut augmenter certains effets comme le gonflement et l’hypothyroïdie. Une mention de cette stratégie dans une étude ou une autre indication de FI n’autorise pas à en faire une étape obligatoire [S4, S6].</p>''','Vérifier le produit et l’objectif avant les unités. La dosimétrie est individuelle et ne remplace pas l’évaluation de la compression [S4, S6, S7].'))
P.append(sec('p-5','Radioiode : contre-indications, interactions et entourage','''<p>La FI Curium juillet2022 contre-indique grossesse existante, supposée ou non exclue et allaitement. Elle demande un sevrage au moins huit semaines avant, sans reprise de cet allaitement. Le guide européen2023 évoque six semaines : cette différence n’est pas effacée et le libellé du produit reste identifié. Le conseil de projet de grossesse de la FI évoque six à douze mois, tandis que sa rubrique contraception mentionne six mois après affection bénigne ; le plan doit être clarifié avec le service plutôt que choisir silencieusement un seul nombre [S4, S6].</p><p>La capsule est aussi contre-indiquée en cas de dysphagie, sténose ou certaines lésions digestives selon le libellé. C’est un point particulièrement pertinent devant un goitre compressif : ne pas demander de forcer la déglutition. Rechercher hypersensibilité aux composants et les conditions qui changent l’exposition ou la sécurité [S6].</p><p>Contraste, amiodarone, hormones, thyréostatiques et produits iodés peuvent modifier la fixation. La FI donne des délais indicatifs selon produit, avec une incohérence interne de deux versus trois jours pour certains thyréostatiques ; elle ne sert pas à organiser un arrêt autonome. Le service coordonne avec le prescripteur, notamment cardiologue pour amiodarone. Après contraste iodé hydrosoluble, la FI indique six à huit semaines ; le guide2021 recommande éviter scintigraphie/radioiode pendant un à deux mois selon contexte [S6, S12].</p><p>Les effets possibles incluent hypothyroïdie, hyperthyroïdie transitoire, inflammation/gonflement et atteinte salivaire. Le risque dépend de l’activité, de l’indication et du terrain ; ne pas annoncer des fréquences de traitement carcinologique à tout goitre bénin. Les consignes de proximité, d’hygiène et de sortie sont écrites et orales, individualisées pour protéger entourage et environnement. Le fractionnement pour éviter une hospitalisation n’est pas autorisé par la directive suisse [S6, S7].</p>''','Grossesse, allaitement, déglutition et interactions sont vérifiés avant la capsule. Les divergences de délais doivent être résolues par l’équipe, pas masquées [S4, S6, S7].'))
P.append(sec('p-6','Iode nutritionnel : concentration et apport total','''<p>Le sel enrichi suisse contient25mg d’iode par kilogramme, soit25µg par gramme de sel :25mg=25000µg et1kg=1000g. Ce calcul explique une concentration ; il ne recommande pas de manger davantage de sel pour atteindre un apport. Choisir le sel iodé dans une consommation modérée et considérer les autres aliments est la stratégie institutionnelle [S8, S11].</p><p>Les compléments se jugent sur l’apport total, le besoin et le terrain. Le conseil institutionnel d’un apport total de250µg/j pendant allaitement ne signifie pas un comprimé de250µg à ajouter automatiquement. Le petit essai de17paires mère-enfant explore des doses ; son intervalle expérimental n’est pas une prescription générale. L’OSAV conseille notamment de poursuivre pendant allaitement le complément iodé commencé en grossesse, avec vérification de l’ensemble des apports [S10].</p><p>Le guide européen ne recommande pas de supplément d’iode ou de sélénium systématique en population suffisamment couverte. Les algues ont des teneurs variables et peuvent apporter un excès. Une réaction à un contraste n’est pas une allergie universelle à l’iode alimentaire ; un régime pauvre en iode avant radioiode est une consigne temporaire de procédure, pas un régime permanent à imposer à toute maladie thyroïdienne [S3, S8, S11].</p>''','Lire concentration, apport total et objectif séparément. Ni plus de sel ni plus de complément n’est une réponse automatique à E04 [S3, S8–S11].'))
pop('tsh','Thyréostimuline : commande et interprétation','<p>La thyréostimuline, ou TSH, est une hormone hypophysaire régulant les cellules folliculaires. Sa valeur s’interprète avec méthode et intervalle du laboratoire, âge, grossesse, médicaments et contexte. Une valeur normale ne prouve pas la bénignité d’un nodule ; une valeur basse demande exploration fonctionnelle et discussion de scintigraphie. Le dosage n’est pas une mesure du volume ni une image des cellules [S3, S5, S14].</p>')
pop('tirads','EU-TIRADS : score, taille et exceptions',us_table+'<p>Ce tableau concerne l’adulte. Un ganglion pathologique ou une extension suspectée peut modifier l’indication ; seuils adultes non transposables directement à l’enfant. La catégorie n’est pas un diagnostic histologique et ne contient pas à elle seule toute l’analyse des ganglions [S3, S13].</p>')
pop('cyto','Bethesda : résultat de cytologie et concordance',cyto_table+'<p>Le guide européen2023 s’appuie sur les catégories de l’édition2017 et signale la troisième édition parue après manuscrit. Pas de pourcentages anciens présentés comme absolus2026. Une discordance entre cytologie bénigne et échographie très suspecte demande une réévaluation [S3].</p>')
pop('croissance','Croissance : dénominateur et deux dimensions','<p>Variation en pourcentage=(nouveau−ancien)÷ancien×100. Exemple fictif20→24mm :4÷20×100=20%, avec4mm de différence. Le critère complet demande au moins20% dans deux diamètres avec2mm minimum, ou volume augmenté de plus50%. Un seul diamètre ne suffit donc pas ; une croissance motive une réévaluation et ne prouve pas seule un cancer [S3].</p>')
pop('levothyroxine','Euthyrox : FI et indication clinique',lt4_table+'<p>FI février2023, produitGTIN7680549490017. Le guide nodulaire2023 déconseille les hormones en maladie nodulaire euthyroïdienne ; la dose de FI ne rend pas le traitement obligatoire. Microgramme et milligramme diffèrent d’un facteur1000. Surtraitement cardiaque et osseux, indication et suivi sont discutés [S3, S5].</p>')
pop('interactions','Lévothyroxine : absorption et analyses',interaction_table+'<p>La biotine peut modifier les tests ; informer le laboratoire et préciser produit/dose. Les délais sont ceux de la FI février2023, pas un délai universel pour chaque molécule. Une grossesse exige de maintenir une substitution nécessaire et de suivre les besoins ; elle ne crée pas une indication de suppression pour tout nodule [S5].</p>')
pop('radioiode','Iode131 thérapeutique : produit et objectif',radio_table+'<p>FI juillet2022, GTIN7680527280012, pas indication de cancer copiée vers goitre. Grossesse/allaitement contreindiqués, précautions de déglutition et rein. Effet retardé et risque gonflement : besoin de décompression rapide contreindique cette stratégie dans le guide spécialisé [S4, S6].</p>')
pop('contraste','Contraste iodé : risque ciblé et calendrier','<p>Une autonomie nodulaire peut exister malgré une fonction normale avant contraste. Le guide2021 ne demande pas de contrôle systématique chez toute personne ; TSH ciblée chez sujets à risque et contrôle après trois à quatre semaines dans certains terrains à haut risque, notamment âgés/cardiaques. Le contraste peut réduire fixation scintigraphique/radioiode ; délai usuel un à deux mois selon contexte. Ne pas retarder une imagerie vitale par un algorithme ambulatoire [S12].</p>')
pop('semio','Sémiologie : signe, mécanisme, test, action','<p>Décrire masse, douleur, évolution, voix, respiration et déglutition ; comprendre les rapports puis choisir bilan de fonction, échographie, prélèvement ou imagerie d’extension. Une TSH normale n’exclut ni cancer ni compression. Stridor/détresse : urgence adaptée. Le premier onglet scientifique développe neuf étapes et leurs sources [S3, S4, S14].</p>')
pop('iode','Iode stable : concentration et apport total','<p>Sel iodé25mg/kg=25µg/g ; c’est une concentration, pas une dose quotidienne prescrite. L’apport total inclut alimentation et compléments ; l’OSAV déconseille d’augmenter le sel pour l’iode. Pendant allaitement250µg/j est un besoin total indiqué par les institutions, pas un comprimé universel à ajouter. Une carence causale établie oblige aussi à reconsidérer la classification E04 [S2, S8–S11].</p>')
pop('profiles','PROFILES : compétence et situations','<p>Le document suisse2017 demande inspection/palpation des structures cervicales et de la thyroïde ; les situations incluent gonflement du cou/goitre et hormones thyroïdiennes anormales. Lien pédagogique à examen, raisonnement et communication, pas correspondance officielle CIM–PROFILES ni question garantie. Aucune numérotation héritée de coque n’est certifiée ici [S16].</p>')
pop('eta','Guide européen adulte2023 : périmètre','<p>European Thyroid Association : recommandations de gestion des nodules thyroïdiens adultes, publiées2023. Le bilan repose sur clinique, fonction et échographie ; la prise en charge tient compte risque, symptômes, préférences et limites des tests. Seuils adultes non directement pédiatriques ; recommandations et FI n’ont pas le même rôle [S3, S13].</p>')
