  x=re.sub(r'(?<=[a-zéèêûùîïàç])(?=\d)',' ',x);x=re.sub(r'(?<=\d)(?=[A-Za-zÀ-ÿ])',' ',x);x=re.sub(r'([:;])(?=\d)',r'\1 ',x);x=re.sub(r'(?<=%)(?=[A-Za-zÀ-ÿ])',' ',x);x=re.sub(r'(?<=[A-Za-zÀ-ÿ]),(?=\d)',', ',x);x=re.sub(r',(?=[A-Za-zÀ-ÿ])',', ',x);x=re.sub(r'([:;])(?=[A-Za-zÀ-ÿ])',r'\1 ',x);x=re.sub(r'([≤≥])',r' \1 ',x);x=x.replace('&lt;',' &lt; ').replace('&gt;',' &gt; ');x=re.sub(r'(?<=[\w])>(?=[0-9−])',' > ',x)
